  $ws=Read-SpectraBootstrapJson (Join-Path $workspacePath 'workspace.yaml');$entry=[ordered]@{workspace_id=$WorkspaceId;customer_id=[string]$ws.customer_id;project_id=if($ProjectId){$ProjectId}else{$null};profile=$Profile;mode=$Mode;relative_path=$relative;release_version=$Binding.version;release_tag=$Binding.tag;release_commit=$Binding.commit;release_tree=$Binding.tree;release_digest=$Binding.digest;registered_at=$ObservedAt;status='active'};$registry.entries=@($registry.entries)+@($entry);$registry.entries=@($registry.entries|Sort-Object workspace_id);Test-SpectraProjectRegistry $registry $root $ProductRoot|Out-Null;Write-SpectraBootstrapJson $path $registry;[ordered]@{status='REGISTERED';writes_performed=$true;relative_path=$relative}
