function New-SpectraTwinHandoff([string]$Workspace,[string]$WorkspaceId,[string]$ProjectId,[string]$SnapshotPath,$Binding,[string]$ObservedAt){
  $root=[IO.Path]::GetFullPath($Workspace);$snapshot=[IO.Path]::GetFullPath($SnapshotPath);Assert-SpectraNoLinkPath $root $snapshot;if(-not(Test-Path $snapshot -PathType Leaf)){throw 'BOOTSTRAP_SNAPSHOT_MISSING'};. (Join-Path $PSScriptRoot 'PortableSnapshot.Catalog.ps1');$snapshotObject=Read-PortableJson $snapshot;Test-PortableSnapshotObject $snapshotObject|Out-Null;$workspaceObject=Read-SpectraBootstrapJson (Join-Path $root 'workspace.yaml');if([string]$workspaceObject.customer_id-cne[string]$snapshotObject.customer_id-or[string]$ProjectId-cne[string]$snapshotObject.project_id){throw 'BOOTSTRAP_SNAPSHOT_SCOPE_MISMATCH'}
