  $releasedSnapshot=Join-Path $releaseDir 'snapshot.json';if((Get-SpectraBootstrapSha $releasedSnapshot)-cne$digest){throw 'BOOTSTRAP_SNAPSHOT_IMMUTABILITY_CONFLICT'};$relative="snapshots/releases/$releaseId/snapshot.json";$handoff=[ordered]@{schema_version=1;product_id='spectra';workspace_id=$WorkspaceId;customer_id=[string]$snapshotObject.customer_id;project_id=$ProjectId;snapshot_id=[string]$snapshotObject.snapshot_id;release_manifest_path=$releaseRelative;snapshot_path=$relative;snapshot_sha256=$digest;release_version=$Binding.version;release_commit=$Binding.commit;created_at=$ObservedAt;read_only=$true};Test-SpectraBootstrapSchema $handoff 'spectra-twin-handoff.schema.json';$path=Join-Path $root 'twin-handoff.json';if(Test-Path $path){$old=Read-SpectraBootstrapJson $path;if(($old|ConvertTo-Json -Depth 20 -Compress)-ceq($handoff|ConvertTo-Json -Depth 20 -Compress)){return [ordered]@{status='ALREADY_CURRENT';writes_performed=$false;path=$path}};throw 'BOOTSTRAP_HANDOFF_CONFLICT'};Write-SpectraBootstrapJson $path $handoff;Write-SpectraBootstrapJson (Join-Path $root 'snapshots\current.json') ([ordered]@{release_id=$releaseId;release_manifest_path=$releaseRelative;snapshot_sha256=$digest});[ordered]@{status='CREATED';writes_performed=$true;path=$path}
