function Test-SpectraTwinHandoff([string]$Workspace){$root=[IO.Path]::GetFullPath($Workspace);$h=Read-SpectraBootstrapJson (Join-Path $root 'twin-handoff.json');Test-SpectraBootstrapSchema $h 'spectra-twin-handoff.schema.json';$snapshot=Join-Path $root ($h.snapshot_path-replace'/',[IO.Path]::DirectorySeparatorChar);$release=Join-Path $root ($h.release_manifest_path-replace'/',[IO.Path]::DirectorySeparatorChar);if((Get-SpectraBootstrapSha $snapshot)-cne[string]$h.snapshot_sha256){throw 'BOOTSTRAP_SNAPSHOT_DIGEST_MISMATCH'};. (Join-Path $PSScriptRoot 'PortableSnapshot.Catalog.ps1');$r=Read-PortableJson $release;Test-PortableSchema $r 'portable-snapshot-release.schema.json';$s=Read-PortableJson $snapshot;Test-PortableSnapshotObject $s|Out-Null;if([string]$r.snapshot_sha256-cne[string]$h.snapshot_sha256-or[string]$r.customer_id-cne[string]$h.customer_id-or[string]$r.project_id-cne[string]$h.project_id){throw 'BOOTSTRAP_HANDOFF_RELEASE_MISMATCH'};$http=[Convert]::FromBase64String([string]$r.transports.http.content_base64);$bytes=[IO.File]::ReadAllBytes($snapshot);if($http.Length-ne$bytes.Length){throw 'BOOTSTRAP_HANDOFF_TRANSPORT_MISMATCH'};$true}
